recorder:
// Records node:crypto behaviour for the cases of a controls file. Usage (Node 24.18.1):
//   docker run --rm -i -v "$PWD":/w node:24.18.1-alpine node /w/recorder.js < controls.json > recorded.json
// Reads { cases: [{ id, fn, args, isolate? }] } and writes the same document with a `result` per case.
// Argument notation: { $: 'undefined' | 'cb' | 'fn' | 'sym' }, { $: 'big', v }, { $: 'buffer' | 'u8' | 'ab' | 'dv' | 'u16', hex }.
const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
function decode(value, callback) {
  if (Array.isArray(value)) return value.map(item => decode(item, callback));
  if (value === null || typeof value !== 'object') return value;
  if (typeof value.$ === 'string') {
    switch (value.$) {
      case 'undefined': return undefined;
      case 'cb': return callback;
      case 'fn': return function () {};
      case 'sym': return Symbol('s');
      case 'big': return BigInt(value.v);
      case 'buffer': return Buffer.from(value.hex, 'hex');
      case 'u8': return new Uint8Array(Buffer.from(value.hex, 'hex'));
      case 'u16': { const b = Buffer.from(value.hex, 'hex'); return new Uint16Array(b.buffer.slice(b.byteOffset, b.byteOffset + b.length)); }
      case 'ab': { const b = Buffer.from(value.hex, 'hex'); return b.buffer.slice(b.byteOffset, b.byteOffset + b.length); }
      case 'dv': { const b = Buffer.from(value.hex, 'hex'); return new DataView(b.buffer.slice(b.byteOffset, b.byteOffset + b.length)); }
    }
  }
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, decode(item, callback)]));
}
function details(value) {
  if (value === undefined) return undefined;
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, typeof item === 'bigint' ? `${item}n` : item]));
}
function summary(value) {
  if (value === undefined) return { t: 'undefined' };
  if (value === null) return { t: 'null' };
  if (typeof value === 'bigint') return { t: 'bigint', bits: value === 0n ? 0 : value.toString(2).length };
  if (typeof value === 'string') return { t: 'string', line: value.split('\n')[0] };
  if (typeof value !== 'object') return { t: typeof value, v: value };
  if (value instanceof Error) {
    const out = { t: 'error', name: value.name, message: value.message };
    for (const key of ['code', 'library', 'reason', 'opensslErrorStack']) if (value[key] !== undefined) out[key] = value[key];
    out.own = Object.keys(value);
    return out;
  }
  if (value instanceof ArrayBuffer) return { t: 'ArrayBuffer', bytes: value.byteLength };
  if (Buffer.isBuffer(value)) return { t: 'Buffer' };
  if (value instanceof crypto.KeyObject) {
    const out = { t: 'KeyObject', ctor: value.constructor.name, type: value.type };
    if (value.type === 'secret') out.size = value.symmetricKeySize;
    else { out.akt = value.asymmetricKeyType; out.details = details(value.asymmetricKeyDetails); }
    return out;
  }
  if ('publicKey' in value && 'privateKey' in value) return { t: 'pair', keys: Object.keys(value), publicKey: summary(value.publicKey), privateKey: summary(value.privateKey) };
  if (typeof value.kty === 'string') return { t: 'jwk', kty: value.kty, crv: value.crv, keys: Object.keys(value).sort() };
  return { t: 'object', ctor: value.constructor && value.constructor.name };
}
function run(item) {
  return new Promise(resolve => {
    const result = {};
    const warnings = [];
    const emit = process.emitWarning;
    process.emitWarning = (...args) => { warnings.push(args); };
    const finish = () => { process.emitWarning = emit; if (warnings.length > 0) result.warnings = warnings; resolve(result); };
    let sync = true, expectsCallback = false, timer;
    const callback = function (...args) {
      result.callback = { sync, this: this === undefined ? 'undefined' : this === null ? 'null' : this.constructor && this.constructor.name, args: args.map(summary) };
      clearTimeout(timer);
      finish();
    };
    const args = decode(item.args, callback);
    expectsCallback = args.includes(callback);
    try { result.returned = summary(crypto[item.fn](...args)); }
    catch (error) { result.threw = summary(error); expectsCallback = false; }
    sync = false;
    if (!expectsCallback) finish();
    else timer = setTimeout(() => { result.callback = 'never'; finish(); }, 20000);
  });
}
async function main() {
  let text = '';
  for await (const chunk of process.stdin) text += chunk;
  const document = JSON.parse(text);
  if (process.argv[2] === 'one') { process.stdout.write(JSON.stringify(await run(document))); return; }
  for (const item of document.cases) {
    if (item.isolate === true) {
      const child = spawnSync(process.execPath, [__filename, 'one'], { input: JSON.stringify(item), timeout: 4000, encoding: 'utf8' });
      item.result = child.error !== undefined ? { hangs: true } : child.status !== 0 ? { crashes: String(child.stderr).split('\n').slice(0, 3).join(' | ') } : JSON.parse(child.stdout);
    } else item.result = await run(item);
  }
  document.node = process.version; document.openssl = process.versions.openssl;
  process.stdout.write(JSON.stringify(document, null, 1));
}
main();
